package com.zorykai.fishing;
import com.cobblemon.mod.common.api.pokemon.*;
import com.cobblemon.mod.common.item.PokemonItem;
import com.google.gson.JsonObject;
import net.minecraft.item.*;
import net.minecraft.registry.Registries;
import net.minecraft.util.Identifier;
import java.util.*;
import static com.zorykai.fishing.GameConfig.*;
public final class FishingStyle {
 public static String name(String species){var s=PokemonSpecies.getByIdentifier(Identifier.of(species.contains(":")?species:"cobblemon:"+species));return s==null?species.replace("cobblemon:",""):s.getName();}
 public static ItemStack pokemon(String species,boolean shiny){try{var s=PokemonSpecies.getByIdentifier(Identifier.of(species.contains(":")?species:"cobblemon:"+species));if(s!=null)return PokemonItem.from(s,shiny?new String[]{"shiny"}:new String[0],1);}catch(IllegalArgumentException invalid){}return new ItemStack(Items.COD);}
 public static Item rodItem(JsonObject definition,String id){String fallback=switch(id){case "boa"->"cobblemon:great_rod";case "super"->"cobblemon:ultra_rod";default->"cobblemon:poke_rod";};var key=Identifier.of(str(definition,"item",fallback));var item=Registries.ITEM.get(key);if(!(item instanceof FishingRodItem))throw new IllegalArgumentException("A aparência da vara deve ser um item de pesca válido: "+key);return item;}
 public static String money(Number amount){return "$ "+java.text.NumberFormat.getNumberInstance(Locale.forLanguageTag("pt-BR")).format(amount);}
 public static String label(String id){return switch(id){case "main"->"Expedição de Pesca";case "areas"->"Mapa dos Lagos";case "armazem","storage"->"Coleção de Capturas";case "perfil","profile"->"Diário do Pescador";case "varas","rods"->"Arsenal de Varas";case "iscas","baits"->"Caixa de Iscas";case "bolas","pokeballs"->"Poké Bolas de Pesca";case "melhorias","upgrades"->"Oficina do Pescador";case "missoes","missions"->"Pedidos da Vila";case "tempo","time-shop"->"Tempo de Expedição";case "conquistas","achievements"->"Marcas de uma Jornada";case "torneios","tournaments"->"Desafios das Marés";case "ranking","rankings"->"Lendas dos Lagos";case "dex"->"Caderno de Espécies";case "museu","museum"->"Galeria de Memórias";case "prestigio","prestige"->"Novo Horizonte";case "tesouros","treasures"->"Achados das Profundezas";case "pendencia"->"Balcão de Atendimento";case "recordes","records"->"Grandes Descobertas";case "premios"->"Prêmios da Expedição";case "eventos"->"Notícias das Marés";case "recarga","cooldown-shop"->"Recarga Acelerada";default->"Detalhes da Captura";};}
 public static String story(String id){return switch(id){case "areas"->"Há uma história escondida em cada margem. Encontre o seu próximo destino.";case "armazem","storage"->"Cada captura guarda a lembrança de uma disputa com as águas.";case "perfil","profile"->"Toda lenda começou com uma vara simples e muita curiosidade.";case "varas","rods"->"Artesãos da vila prepararam estas varas para acompanhar sua jornada.";case "iscas","baits"->"Uma pequena escolha pode atrair uma grande surpresa das profundezas.";case "bolas","pokeballs"->"A última etapa de uma boa pescaria merece o equipamento certo.";case "melhorias","upgrades"->"A oficina transforma experiência em ferramentas para novas aventuras.";case "missoes","missions"->"Os moradores contam com suas descobertas. Aceite um novo desafio.";case "dex"->"Um registro de encontros, cores e espécies que cruzaram sua linha.";case "museu","museum"->"Algumas histórias valem mais quando são guardadas com carinho.";case "torneios","tournaments"->"O sino do cais anuncia uma nova disputa entre os pescadores.";case "tesouros","treasures"->"As águas devolvem objetos de jornadas que vieram antes da sua.";default->"Novas histórias esperam por você nas águas de Zorykai.";};}
 public static Item icon(String id){return switch(id){case "areas"->Items.FILLED_MAP;case "armazem"->Items.CHEST;case "perfil"->Items.NAME_TAG;case "varas"->Registries.ITEM.get(Identifier.of("cobblemon:poke_rod"));case "iscas"->Items.TROPICAL_FISH;case "bolas"->Registries.ITEM.get(Identifier.of("cobblemon:poke_ball"));case "melhorias"->Items.ANVIL;case "missoes"->Items.WRITABLE_BOOK;case "tempo","recarga"->Items.CLOCK;case "conquistas"->Items.GOLDEN_APPLE;case "torneios"->Items.NAUTILUS_SHELL;case "ranking","recordes"->Items.GOLD_INGOT;case "dex"->Items.BOOK;case "museu","prestigio"->Items.NETHER_STAR;case "tesouros","premios"->Items.DIAMOND;case "pendencia"->Items.PAPER;case "eventos"->Items.BELL;default->Items.COMPASS;};}
 public static List<String> wrap(String text){var out=new ArrayList<String>();StringBuilder row=new StringBuilder();for(var word:text.split(" ")){if(row.length()+word.length()>34&&!row.isEmpty()){out.add("&8&o"+row);row.setLength(0);}if(!row.isEmpty())row.append(' ');row.append(word);}if(!row.isEmpty())out.add("&8&o"+row);return out;}
 public static int mainSlot(int slot){return switch(slot){case 0->10;case 2->12;case 3->13;case 4->14;case 5->19;case 6->20;case 7->21;case 8->22;case 9->23;case 10->24;case 11->25;case 12->28;case 13->29;case 14->30;case 15->31;case 16->32;case 17->33;case 18->34;case 19->37;case 20->38;case 21->39;case 22->40;default->slot;};}
 private FishingStyle(){}
}
